# test_leap.py (run it with: pytest)
def is_leap(year):
    return year % 4 == 0 and (year % 100 != 0 or year % 400 == 0)

def test_leap_years():
    assert is_leap(2000)
    assert is_leap(2024)

def test_century_rule():
    assert not is_leap(1900)

# pytest finds the test_ functions and reports "2 passed"

// a function like left-pad, and the built-in that replaced it
function leftPad(str, len, ch = " ") {
  str = String(str);
  while (str.length < len) str = ch + str;
  return str;
}
leftPad(5, 3, "0");          // "005"
String(5).padStart(3, "0");  // "005", no dependency needed

function total(prices: number[]): number {
  return prices.reduce((sum, p) => sum + p, 0);
}

total([12.5, 3]);   // 15.5
total("12.5");      // error TS2345: Argument of type 'string' is not assignable to parameter of type 'number[]'.
